# 1. 最小 Bash Agent 核心循环（课堂约 150 行原型之协议骨架）
while True:
    user_input = read_from_terminal()
    messages.append({"role": "user", "content": user_input})

    while True:
        reply = call_chat_completions_api(messages, tools=[bash_tool_schema])
        messages.append(reply)

        if not reply.get("tool_calls"):
            print(reply["content"])
            break

        for tool_call in reply["tool_calls"]:
            if tool_call["function"]["name"] == "bash":
                cmd = parse_json(tool_call["function"]["arguments"])["command"]
                # 注意：原型中硬编码 timeout 易因网络/环境差异误杀正常任务
                output = run_bash(cmd, timeout=30)
                messages.append({
                    "role": "tool",
                    "tool_call_id": tool_call["id"],
                    "content": output
                })

# 2. 带停止条件与预算控制的受控 Ralph Loop 伪代码
# 原始骨架：while true; do cat PROMPT.md | claude -p; done
for step in range(MAX_STEPS):
    output = run_agent_new_session(prompt_file="PROMPT.md", workspace=".")
    if "RALPH_DONE" in output and verify_acceptance_criteria(workspace="."):
        break
